include "../../base.thrift"
include "../common.thrift"
struct SendNotificationCardRequest {
1: required common.CommonInfo common_info // 端状态上报链路中会携带所需参数
2: required Widget widget
255: base.Base Base
}
struct SendNotificationCardResponse {
1: required string widget_request_id // 返回传入的 widget_request_id 字段
255: base.BaseResp BaseResp
}

struct Widget {
1: required string widget_id // 触发器传入 types.WidgetIDDoubaoFlash, // 定义 WidgetIDDoubaoFlash="doubao_flash" 豆包闪念卡，phud也需要新增一个
2: required WidgetData widget_data
}
struct WidgetData {
1: optional WidgetTitle title // 触发器传入空
2: required string widget_request_id // 触发器传入 uuid
3: optional string view_data // 业务数据，触发器传入 "{\"effect_ids\":[\"cabin_always_on\",\"driver_fatigue_alert\",\"driver_distraction_alert\",\"cabin_face_identification\",\"front_occupant_phone_call_alert\",\"driver_gaze_tracking\",\"vehicle_gesture_control\",\"cabin_occupant_sleep\",\"cabin_pet_presence\",\"front_occupant_head_temperature\",\"exterior_face_identification\",\"exterior_luggage_detection\",\"exterior_charging_station_detection\"]}"
4: optional string content // 新增字段，触发器传入后台配置的指定文本，AIDV 的代码里也加一下这个字段
}
struct WidgetTitle {
1: optional string title
2: optional string desc
3: optional IconItem icon
}
struct IconItem {
1: optional string light_url // 白天，一般只需要这个
2: optional string dark_url // 默认
3: optional string icon_type // 图标类型，默认是图片
}

func (s *AIDVServiceImpl) SendNotificationCard(
ctx context.Context,
req *aidvtrigger.SendNotificationCardRequest,
) (*aidvtrigger.SendNotificationCardResponse, error) {
if req == nil || req.GetCommonInfo() == nil || req.GetCommonInfo().GetDeviceId() <= 0 {
return nil, errors.New("params err: common_info.device_id is required")
}
rpcWidget := req.GetWidget()
if rpcWidget == nil || rpcWidget.GetWidgetData() == nil {
return nil, errors.New("params err: widget and widget_data are required")
}
rpcData := rpcWidget.GetWidgetData()
widgetRequestID := strings.TrimSpace(rpcData.GetWidgetRequestId())
content := strings.TrimSpace(rpcData.GetContent())
if rpcWidget.GetWidgetId() != types.WidgetIDDoubaoFlash ||
widgetRequestID == "" || content == "" || strings.TrimSpace(rpcData.GetViewData()) == "" {
return nil, errors.New("params err: invalid notification card widget")
}
// CustomKitex 已将 IDL common_info 写入 context；发送前再校验一次，
// 避免 SendNewWidgetMessage 因取不到 device_id 而仅记录日志后返回。
commonInfo, err := types.GetCommonInfoFromContext(ctx)
if err != nil || commonInfo.DeviceID <= 0 {
return nil, errors.New("rpc common_info is missing from context")
}
widget := types.Widget{
WidgetID: types.WidgetIDDoubaoFlash,
WidgetData: types.WidgetData{
WidgetRequestID: widgetRequestID,
Title: types.WidgetTitle{
Title: "",
Desc: "",
},
ViewData: rpcData.GetViewData(),
},
}
frontier.SendNewWidgetMessage(ctx, widget)
return &aidvtrigger.SendNotificationCardResponse{
WidgetRequestId: widgetRequestID,
BaseResp: base.NewBaseResp(),
}, nil
}
